def lcm_search(a: int, b: int) -> int:
    a = abs(a)
    b = abs(b)
    if a == 0 or b == 0:
        return 0
    m = max(a, b)
    step = m
    while m % a != 0 or m % b != 0:
        m += step
    return m

def lcm_gcd(a: int, b: int) -> int:
    a = abs(a)
    b = abs(b)
    if a == 0 or b == 0:
        return 0
    return a // math.gcd(a, b) * b
